def solve(ki,Kv,Kh):
    H,W=len(ki),len(ki[0])
    P=pieces(ki)
    # vertical: repeatedly drop pieces (per column independence? use piece-level: piece can descend if min gap >= Kv... simpler: piece stops when exists occupied cell in overlapping columns with <=Kv empty rows between)
    def can_descend(piece,occ,Kv):
        r0=min(p[0] for p in piece); r1=max(p[0] for p in piece)
        cols=set(c for _,c in piece)
        for r in range(r0,r1+2):
            for c in cols:
                if (r+1,c) in occ and (r,c) not in occ:
                    gap=(r+1)-r-1  # empty rows between r and occupied r+1
                    if gap < Kv: return False
        return True
    def can_slide(piece,occ,Kh):
        rows=set(r for r,_ in piece)
        for r in rows:
            for c in range(min(c for _,c in piece)-1,-1,-1):
                if (r,c+1) in occ:
                    gap=(c+1)-c-1
                    if gap < Kh: return False
        return True
    placed=[]  # list of (col, cells rel offset top)
    res=[[0]*W for _ in range(H)]
    # assign vertical: drop each piece to lowest possible respecting constraints, iterating until fixpoint
    cur={p[:]:(p[0],p[1]) for p in []}
    for col,pts in P:
        pass
    # iterative fixpoint: each piece moves down while can_descend, left while can_slide; loop until stable
    g=[[0]*W for _ in range(H)]
    pos={}
    for idx,(col,pts) in enumerate(P):
        r0=min(p[0] for p in pts); c0=min(p[1] for p in pts)
        pos[idx]=(r0,c0)
    changed=True
    while changed:
        changed=False
        occupied=set()
        for i,(r0,c0) in pos.items():
            for dr,dc in [(r0+r,c0+c) for r,c in [(p[0]-pos[i][0],p[1]-pos[i][1]) for p in [P[i][1]]]]:
                occupied.add((dr,dc))
        for i,(col,pts) in enumerate(P):
            r0,c0=pos[i]
            newr,newc=r0,c0
            # slide left
            if can_slide(pts,occupied,Kh):
                while newc>0:
                    newc-=1
                    if not can_slide(pts,occupied,Kh): break
                if newc!=c0: changed=True
            # fall
            if can_descend(pts,{(q[0],q[1]) for k2,(q0,q1) in pos.items() if k2!=i},Kv):
                while newr+1<H and all(((newr+1+rr),(newc+cc)) not in occupied or True for rr,cc in [(p[0]-r0,p[1]-c0) for p in pts]):
                    newr+=1
                    if not can_descend(pts,{(q0,q1) for k2,(q0,q1) in pos.items() if k2!=i},Kv): break
                if newr!=r0: changed=True
            pos[i]=(newr,newc)
    for i,(r0,c0) in pos.items():
        for rr,cc in [(p[0]-pos[i][0],p[1]-pos[i][1]) for p in [P[i][1]]]:
            g[r0+rr][c0+cc]=P[i][0]
    return g
