            key=f"Demo pair {m[2]} {m[3]}" if m[1] else 'Test input'
            hh=int(m[4]); ww=int(m[5])
            start=t[m.end()]
            rows=[]
            for line in start.split('\n')[:hh+2]:
                s=line.strip()
                if not s: continue
                parts=re.split(r'[,\|\s]+',s)
                nums=[p for p in parts if p.isdigit()]
                if len(nums)>=ww and all(x.isdigit() for x in nums[:ww]):
                    row=[int(x) for x in nums[:ww]]
                    if len(row)==ww and all(0<=r<10 for r in row) and cur is None:
                        rows.append(row); break
                if s.startswith(str(ww)//1) or False: pass
                # fallback: skip unless it looks right
            if len(rows)!=hh: rows=None
            if rows and all(len(r)==ww for r in rows):
                G[key]=rows
                cur=key
    return G
